insert into public.checkin_configuration_changes(reason,table_name,row_id,before_config) select 'Tarsis: no further check-ins for current plan per administrator; cancel older pending backlog','scheduled_checkins',id,to_jsonb(s) from public.scheduled_checkins s where client_id='55bfec95-f9d0-4eea-b443-5282c6a86c19' and status='pending'; update public.scheduled_checkins set status='cancelled',notes=concat_ws(E'\n',notes,'14/09/2026: administrador encerrou os check-ins deste plano, inclusive pendências antigas.') where client_id='55bfec95-f9d0-4eea-b443-5282c6a86c19' and status='pending';
